run_era5_mintemp_pipeline <- function(config_path="config/era5_mintemp.yml",mode=c("diagnose","plan","download","process","aggregate","estimate","full"),dry_run=TRUE,observed_end=NULL,future_end=NULL,data_root=NULL,overwrite=FALSE,rebuild_all_weeks=FALSE) { mode<-match.arg(mode); root<-resolve_project_root(dirname(config_path)); cfg<-resolve_config_paths(read_pipeline_config(config_path),root); if(!is.null(data_root)) { cfg$paths$data_root<-normalizePath(data_root,winslash="/",mustWork=FALSE); defaults<-c(raw="raw_data/ERA5_min_temp_daily",daily="processed_data/mintemp_daily",weekly="processed_data/mintemp_weekly",run="pipeline_runs/cds_datagrab"); for(n in names(defaults)) cfg$paths[[paste0(n,"_dir")]]<-file.path(cfg$paths$data_root,unname(cfg$paths[[paste0(n,"_subdir")]]%||%defaults[[n]])) }; if(!is.null(observed_end)) cfg$temporal$observed_end<-as.Date(observed_end); if(!is.null(future_end)) cfg$temporal$future_end_date<-as.Date(future_end); cfg<-validate_pipeline_config(cfg); template_before<-template_fingerprint(cfg$spatial$template_path); m<-initialize_run_manifest(cfg,mode); invd<-inventory_grid_directory(cfg$paths$daily_dir,cfg$project$output_prefix,"daily",TRUE); invw<-inventory_grid_directory(cfg$paths$weekly_dir,cfg$project$output_prefix,"weekly",TRUE); diag<-diagnose_spatial_domain(cfg$spatial$template_path,cfg$spatial$bbox_path,cfg); if(mode%in%c("diagnose","plan","full","download")) { plan<-plan_observed_update(invd,cfg$temporal$initial_start_date,cfg$temporal$observed_end,cfg$temporal$overlap_days); req<-build_era5_mintemp_requests(plan$date,diag$proposed_cds_area,cfg); write_cds_request_manifests(req,m$run_dir); utils::write.csv(plan,file.path(m$run_dir,"planned_dates.csv"),row.names=FALSE); utils::write.csv(compress_dates_to_intervals(plan$date),file.path(m$run_dir,"planned_intervals.csv"),row.names=FALSE); utils::write.csv(invd,file.path(m$run_dir,"inventory_daily.csv"),row.names=FALSE); utils::write.csv(invw,file.path(m$run_dir,"inventory_weekly.csv"),row.names=FALSE); jsonlite::write_json(diag,file.path(m$run_dir,"spatial_diagnostics.json"),pretty=TRUE,auto_unbox=TRUE); if(mode=="download"||mode=="full") download_cds_requests(req,cfg$paths$raw_dir,m$run_dir,dry_run,overwrite,cfg$cds$batch_workers) } else plan<-data.frame(); if(mode%in%c("aggregate","full")) aggregate_daily_to_weekly(cfg$paths$daily_dir,cfg$paths$weekly_dir,cfg$project$output_prefix,overwrite=TRUE,template_path=cfg$spatial$template_path,rebuild_all=rebuild_all_weeks); if(!identical(template_before,template_fingerprint(cfg$spatial$template_path))) stop("Template fingerprint changed during pipeline"); finalize_run_manifest(m,"success") }
